import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/application/services/extraction-pipeline.ts","src/infrastructure/database/repositories/extraction-log-repository.ts","src/infrastructure/database/schema.ts","src/presentation/cli/commands/extract.ts","src/application/services/extraction-pipeline.test.ts","src/infrastructure/database/repositories/extraction-log-repository.test.ts","tests/infrastructure/database/extraction-audit-identity.test.ts","tests/infrastructure/database/extraction-process-admission.test.ts","src/presentation/cli/commands/extract.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/repositories.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/application/services/extraction-pipeline.ts","kind":"ignore-audit-input-match","from":"return audit.inputIdentity === inputSnapshot;","to":"return true;","pattern":"audit identity survives|audit identity binds"},{"path":"src/application/services/extraction-pipeline.ts","kind":"omit-audit-identity-save","from":"inputIdentity: inputSnapshot,","to":"inputIdentity: undefined,","pattern":"audit identity survives"},{"path":"src/application/services/extraction-pipeline.ts","kind":"allow-unbound-audit","from":"if (!audit.inputIdentity) throw","to":"if (false) throw","pattern":"unbound legacy"},{"path":"src/application/services/extraction-pipeline.ts","kind":"ignore-force","from":"if (!audit || options?.force) return false;","to":"if (!audit) return false;","pattern":"audit identity binds"},{"path":"src/application/services/extraction-pipeline.ts","kind":"ignore-project-binding","from":"\"extraction-input-v1\", sessionId, projectName,","to":"\"extraction-input-v1\", sessionId, null,","pattern":"audit identity binds"},{"path":"src/application/services/extraction-pipeline.ts","kind":"ignore-redacted-input","from":"input.map(message => this.redactor.redactText(message.content).text),","to":"[],","pattern":"audit identity binds"},{"path":"src/presentation/cli/commands/extract.ts","kind":"restore-existence-only-cli-filter","from":"const sessionsToProcess = filteredSessions;","to":"const sessionsToProcess = []; for (const session of filteredSessions) if(!await logRepo.findById(session.id) || options.force) sessionsToProcess.push(session);","pattern":"cli audit identity survives"},{"path":"src/infrastructure/database/repositories/extraction-log-repository.ts","kind":"drop-persisted-identity","from":"entry.inputIdentity ?? null","to":"null","pattern":"audit identity survives|migrates legacy"},{"path":"src/infrastructure/database/repositories/extraction-log-repository.ts","kind":"omit-read-validation","from":"assertInputIdentity(inputIdentity);","to":"void inputIdentity;","pattern":"corrupted identity"},{"path":"src/infrastructure/database/repositories/extraction-log-repository.ts","kind":"omit-write-validation","from":"assertInputIdentity(entry.inputIdentity);","to":"void entry.inputIdentity;","pattern":"corrupted identity"},{"path":"src/infrastructure/database/schema.ts","kind":"omit-legacy-migration","from":"if (!extractionColumns.some(column => column.name === \"input_identity\"))","to":"if (false)","pattern":"migrates legacy"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local=match[1].startsWith('src/')?match[1]:'src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-audit-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-audit-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-audit-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

